  'Explore tools and tips to grow faster, improve your channel, and reach more viewers.' => 'ವೇಗವಾಗಿ ಬೆಳೆಯಲು, ನಿಮ್ಮ ಚಾನಲ್ ಅನ್ನು ಸುಧಾರಿಸಲು ಮತ್ತು ಹೆಚ್ಚಿನ ವೀಕ್ಷಕರನ್ನು ತಲುಪಲು ಪರಿಕರಗಳು ಮತ್ತು ಸಲಹೆಗಳನ್ನು ಅನ್ವೇಷಿಸಿ.',
  'Loading growth data...' => 'ಬೆಳವಣಿಗೆಯ ಡೇಟಾವನ್ನು ಲೋಡ್ ಮಾಡಲಾಗುತ್ತಿದೆ...',
  'Channel reach' => 'ಚಾನಲ್ ತಲುಪುವಿಕೆ',
  'Engagement rate' => 'ನಿಶ್ಚಿತಾರ್ಥದ ದರ',
  'Discovery videos' => 'ಡಿಸ್ಕವರಿ ವೀಡಿಯೊಗಳು',
  'Growth actions' => 'ಬೆಳವಣಿಗೆಯ ಕ್ರಮಗಳು',
  'Based on your channel data' => 'ನಿಮ್ಮ ಚಾನಲ್ ಡೇಟಾವನ್ನು ಆಧರಿಸಿ',
  'Publish consistently' => 'ಸತತವಾಗಿ ಪ್ರಕಟಿಸಿ',
  'Upload your first video and give viewers a clear reason to subscribe.' => 'ನಿಮ್ಮ ಮೊದಲ ವೀಡಿಯೊವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಮತ್ತು ವೀಕ್ಷಕರಿಗೆ ಚಂದಾದಾರರಾಗಲು ಸ್ಪಷ್ಟ ಕಾರಣವನ್ನು ನೀಡಿ.',
  'Use Shorts for discovery' => 'ಅನ್ವೇಷಣೆಗಾಗಿ ಕಿರುಚಿತ್ರಗಳನ್ನು ಬಳಸಿ',
  'Keep testing quick hooks and link viewers to longer videos.' => 'ತ್ವರಿತ ಹುಕ್‌ಗಳನ್ನು ಪರೀಕ್ಷಿಸುತ್ತಿರಿ ಮತ್ತು ವೀಕ್ಷಕರನ್ನು ದೀರ್ಘ ವೀಡಿಯೊಗಳಿಗೆ ಲಿಂಕ್ ಮಾಡಿ.',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'ನಿಮ್ಮ ಚಾನಲ್ ಇನ್ನೂ ಕಂಡುಬಂದಿಲ್ಲದ ವೀಕ್ಷಕರನ್ನು ತಲುಪಲು ಸಣ್ಣ ಲಂಬ ವೀಡಿಯೊಗಳನ್ನು ರಚಿಸಿ.',
  'Create short' => 'ಚಿಕ್ಕದನ್ನು ರಚಿಸಿ',
  'Turn comments into loyalty' => 'ಕಾಮೆಂಟ್‌ಗಳನ್ನು ನಿಷ್ಠೆಯಾಗಿ ಪರಿವರ್ತಿಸಿ',
  'Reply to recent comments and turn viewers into returning fans.' => 'ಇತ್ತೀಚಿನ ಕಾಮೆಂಟ್‌ಗಳಿಗೆ ಪ್ರತ್ಯುತ್ತರಿಸಿ ಮತ್ತು ವೀಕ್ಷಕರನ್ನು ಹಿಂದಿರುಗುವ ಅಭಿಮಾನಿಗಳನ್ನಾಗಿ ಮಾಡಿ.',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'ನಿಮ್ಮ ಮುಂದಿನ ಅಪ್‌ಲೋಡ್‌ನಲ್ಲಿ ಪ್ರಶ್ನೆಯನ್ನು ಕೇಳಿ ಮತ್ತು ಕಾಮೆಂಟ್‌ಗಳು ಬಂದಾಗ ತ್ವರಿತವಾಗಿ ಉತ್ತರಿಸಿ.',
  'View comments' => 'ಕಾಮೆಂಟ್‌ಗಳನ್ನು ವೀಕ್ಷಿಸಿ',
  'Improve public reach' => 'ಸಾರ್ವಜನಿಕ ವ್ಯಾಪ್ತಿಯನ್ನು ಸುಧಾರಿಸಿ',
