  'Explore tools' => 'ಪರಿಕರಗಳನ್ನು ಅನ್ವೇಷಿಸಿ',
  'Open the right workflow fast' => 'ಸರಿಯಾದ ಕೆಲಸದ ಹರಿವನ್ನು ತ್ವರಿತವಾಗಿ ತೆರೆಯಿರಿ',
  'Upload planner' => 'ಯೋಜಕವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'ಶೀರ್ಷಿಕೆಗಳು, ಟ್ಯಾಗ್‌ಗಳು, ಗೋಚರತೆ ಮತ್ತು ಥಂಬ್‌ನೇಲ್ ಹಂತಗಳೊಂದಿಗೆ ಹೊಸ ಅಪ್‌ಲೋಡ್ ಅನ್ನು ಪ್ರಾರಂಭಿಸಿ.',
  'Shorts studio' => 'ಶಾರ್ಟ್ಸ್ ಸ್ಟುಡಿಯೋ',
