  'Content manager' => 'ವಿಷಯ ನಿರ್ವಾಹಕ',
  'Review visibility, monetization, comments, and performance in one place.' => 'ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ ಗೋಚರತೆ, ಹಣಗಳಿಕೆ, ಕಾಮೆಂಟ್‌ಗಳು ಮತ್ತು ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಪರಿಶೀಲಿಸಿ.',
  'Analytics review' => 'ಅನಾಲಿಟಿಕ್ಸ್ ವಿಮರ್ಶೆ',
  'Track views, likes, comments, publishing status, and trends.' => 'ವೀಕ್ಷಣೆಗಳು, ಇಷ್ಟಗಳು, ಕಾಮೆಂಟ್‌ಗಳು, ಪ್ರಕಾಶನ ಸ್ಥಿತಿ ಮತ್ತು ಪ್ರವೃತ್ತಿಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.',
  'Channel profile' => 'ಚಾನಲ್ ಪ್ರೊಫೈಲ್',
  'Update your bio, channel details, and public creator presence.' => 'ನಿಮ್ಮ ಬಯೋ, ಚಾನಲ್ ವಿವರಗಳು ಮತ್ತು ಸಾರ್ವಜನಿಕ ರಚನೆಕಾರರ ಉಪಸ್ಥಿತಿಯನ್ನು ನವೀಕರಿಸಿ.',
  'Audience building' => 'ಪ್ರೇಕ್ಷಕರ ಕಟ್ಟಡ',
  'Study subscribers, comments, and what viewers respond to most.' => 'ಚಂದಾದಾರರು, ಕಾಮೆಂಟ್‌ಗಳು ಮತ್ತು ಹೆಚ್ಚಿನ ವೀಕ್ಷಕರು ಏನು ಪ್ರತಿಕ್ರಿಯಿಸುತ್ತಾರೆ ಎಂಬುದನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ.',
  'Top content to learn from' => 'ಕಲಿಯಲು ಉನ್ನತ ವಿಷಯ',
  'Upload videos to unlock performance lessons.' => 'ಕಾರ್ಯಕ್ಷಮತೆಯ ಪಾಠಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಲು ವೀಡಿಯೊಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.',
  'Tips to reach more viewers' => 'ಹೆಚ್ಚಿನ ವೀಕ್ಷಕರನ್ನು ತಲುಪಲು ಸಲಹೆಗಳು',
  'Creator checklist' => 'ರಚನೆಕಾರರ ಪರಿಶೀಲನಾಪಟ್ಟಿ',
  'Hook viewers in the first 3 seconds' => 'ಮೊದಲ 3 ಸೆಕೆಂಡುಗಳಲ್ಲಿ ವೀಕ್ಷಕರನ್ನು ಹುಕ್ ಮಾಡಿ',
  'Open with the result, conflict, or visual payoff before adding context.' => 'ಸಂದರ್ಭವನ್ನು ಸೇರಿಸುವ ಮೊದಲು ಫಲಿತಾಂಶ, ಸಂಘರ್ಷ ಅಥವಾ ದೃಶ್ಯ ಪಾವತಿಯೊಂದಿಗೆ ತೆರೆಯಿರಿ.',
  'Make titles searchable' => 'ಶೀರ್ಷಿಕೆಗಳನ್ನು ಹುಡುಕುವಂತೆ ಮಾಡಿ',
  'Use the exact words viewers would type, then keep the promise in the video.' => 'ವೀಕ್ಷಕರು ಟೈಪ್ ಮಾಡುವ ನಿಖರವಾದ ಪದಗಳನ್ನು ಬಳಸಿ, ನಂತರ ವೀಡಿಯೊದಲ್ಲಿ ಭರವಸೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ.',
  'Convert shorts into sessions' => 'ಕಿರುಚಿತ್ರಗಳನ್ನು ಸೆಷನ್‌ಗಳಾಗಿ ಪರಿವರ್ತಿಸಿ',
  'Pin a comment or description link from each short to a related full video.' => 'ಪ್ರತಿ ಕಿರುಚಿತ್ರದಿಂದ ಸಂಬಂಧಿತ ಪೂರ್ಣ ವೀಡಿಯೊಗೆ ಕಾಮೆಂಟ್ ಅಥವಾ ವಿವರಣೆ ಲಿಂಕ್ ಅನ್ನು ಪಿನ್ ಮಾಡಿ.',
  'Refresh underperforming uploads' => 'ಕಡಿಮೆ ಕಾರ್ಯಕ್ಷಮತೆಯ ಅಪ್‌ಲೋಡ್‌ಗಳನ್ನು ರಿಫ್ರೆಶ್ ಮಾಡಿ',
  'Update thumbnails and titles after you have enough impressions to compare.' => 'ನೀವು ಹೋಲಿಸಲು ಸಾಕಷ್ಟು ಇಂಪ್ರೆಶನ್‌ಗಳನ್ನು ಹೊಂದಿದ ನಂತರ ಥಂಬ್‌ನೇಲ್‌ಗಳು ಮತ್ತು ಶೀರ್ಷಿಕೆಗಳನ್ನು ನವೀಕರಿಸಿ.',
  'Upload source' => 'ಮೂಲವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ',
