  'Requires a downloader command such as yt-dlp for media import.' => 'ಮಾಧ್ಯಮ ಆಮದುಗಾಗಿ yt-dlp ನಂತಹ ಡೌನ್‌ಲೋಡರ್ ಆಜ್ಞೆಯ ಅಗತ್ಯವಿದೆ.',
