  'Import a public video URL, customize its details, and publish it through the normal processing pipeline.' => 'ಸಾರ್ವಜನಿಕ ವೀಡಿಯೊ URL ಅನ್ನು ಆಮದು ಮಾಡಿ, ಅದರ ವಿವರಗಳನ್ನು ಕಸ್ಟಮೈಸ್ ಮಾಡಿ ಮತ್ತು ಸಾಮಾನ್ಯ ಪ್ರಕ್ರಿಯೆಯ ಪೈಪ್‌ಲೈನ್ ಮೂಲಕ ಅದನ್ನು ಪ್ರಕಟಿಸಿ.',
  'Video Import' => 'ವೀಡಿಯೊ ಆಮದು',
