  'API Key' => 'API ಕೀ',
  'Not required' => 'ಅಗತ್ಯವಿಲ್ಲ',
  'Save Import Settings' => 'ಆಮದು ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಿ',
  'Video import settings saved.' => 'ವೀಡಿಯೊ ಆಮದು ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಲಾಗಿದೆ.',
  'Video import started.' => 'ವೀಡಿಯೊ ಆಮದು ಪ್ರಾರಂಭವಾಗಿದೆ.',
