  'Video import provider is disabled.' => 'ವೀಡಿಯೊ ಆಮದು ಪೂರೈಕೆದಾರರನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.',
  'Direct imports must use a supported video file URL.' => 'ನೇರ ಆಮದುಗಳು ಬೆಂಬಲಿತ ವೀಡಿಯೊ ಫೈಲ್ URL ಅನ್ನು ಬಳಸಬೇಕು.',
  'Cannot open remote video URL.' => 'ರಿಮೋಟ್ ವೀಡಿಯೊ URL ಅನ್ನು ತೆರೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'Cannot prepare imported video file.' => 'ಆಮದು ಮಾಡಿದ ವೀಡಿಯೊ ಫೈಲ್ ಅನ್ನು ಸಿದ್ಧಪಡಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'Cannot read remote video file.' => 'ರಿಮೋಟ್ ವೀಡಿಯೊ ಫೈಲ್ ಅನ್ನು ಓದಲಾಗುವುದಿಲ್ಲ.',
  'Imported video exceeds the maximum upload size.' => 'ಆಮದು ಮಾಡಿದ ವೀಡಿಯೊ ಗರಿಷ್ಠ ಅಪ್‌ಲೋಡ್ ಗಾತ್ರವನ್ನು ಮೀರಿದೆ.',
  'Remote video file is empty.' => 'ರಿಮೋಟ್ ವೀಡಿಯೊ ಫೈಲ್ ಖಾಲಿಯಾಗಿದೆ.',
  'Video import downloader command is not configured.' => 'ವೀಡಿಯೊ ಆಮದು ಡೌನ್‌ಲೋಡರ್ ಆಜ್ಞೆಯನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗಿಲ್ಲ.',
  'Downloader did not create an importable video file.' => 'ಡೌನ್‌ಲೋಡರ್ ಆಮದು ಮಾಡಿಕೊಳ್ಳಬಹುದಾದ ವೀಡಿಯೊ ಫೈಲ್ ಅನ್ನು ರಚಿಸಿಲ್ಲ.',
  'Import URL is invalid.' => 'ಆಮದು URL ಅಮಾನ್ಯವಾಗಿದೆ.',
  'Import URL must use HTTP or HTTPS.' => 'ಆಮದು URL HTTP ಅಥವಾ HTTPS ಅನ್ನು ಬಳಸಬೇಕು.',
  'Import URL host is invalid.' => 'ಆಮದು URL ಹೋಸ್ಟ್ ಅಮಾನ್ಯವಾಗಿದೆ.',
  'Import URL does not match the selected provider.' => 'ಆಮದು URL ಆಯ್ಕೆಮಾಡಿದ ಪೂರೈಕೆದಾರರಿಗೆ ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.',
  'Import URL host cannot be resolved.' => 'ಆಮದು URL ಹೋಸ್ಟ್ ಅನ್ನು ಪರಿಹರಿಸಲಾಗುವುದಿಲ್ಲ.',
  'Import URL must resolve to a public host.' => 'ಆಮದು URL ಅನ್ನು ಸಾರ್ವಜನಿಕ ಹೋಸ್ಟ್‌ಗೆ ಪರಿಹರಿಸಬೇಕು.',
  'Unknown video import provider.' => 'ಅಜ್ಞಾತ ವೀಡಿಯೊ ಆಮದು ಒದಗಿಸುವವರು.',
  'Saves a public video file URL and plays it from the original URL.' => 'ಸಾರ್ವಜನಿಕ ವೀಡಿಯೊ ಫೈಲ್ URL ಅನ್ನು ಉಳಿಸುತ್ತದೆ ಮತ್ತು ಅದನ್ನು ಮೂಲ URL ನಿಂದ ಪ್ಲೇ ಮಾಡುತ್ತದೆ.',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'YouTube ವಿವರಗಳನ್ನು ಪಡೆಯುತ್ತದೆ ಮತ್ತು YouTube ಎಂಬೆಡ್ ಪ್ಲೇಯರ್‌ನೊಂದಿಗೆ ಪ್ಲೇ ಮಾಡುತ್ತದೆ.',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'ವಿಮಿಯೋ ವಿವರಗಳನ್ನು ಪಡೆಯುತ್ತದೆ ಮತ್ತು ವಿಮಿಯೋ ಎಂಬೆಡ್ ಪ್ಲೇಯರ್‌ನೊಂದಿಗೆ ಪ್ಲೇ ಮಾಡುತ್ತದೆ.',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'ಡೈಲಿಮೋಷನ್ ವಿವರಗಳನ್ನು ಪಡೆಯುತ್ತದೆ ಮತ್ತು ಡೈಲಿಮೋಷನ್ ಎಂಬೆಡ್ ಪ್ಲೇಯರ್‌ನೊಂದಿಗೆ ಪ್ಲೇ ಮಾಡುತ್ತದೆ.',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'ಸಕ್ರಿಯಗೊಳಿಸಿದ ಸೇವೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ಸಾರ್ವಜನಿಕ ವೀಡಿಯೊ URL ಅನ್ನು ಅಂಟಿಸಿ. PlayHub ವಿವರಗಳನ್ನು ತರುತ್ತದೆ ಮತ್ತು ಅದನ್ನು ಮೂಲ ಪೂರೈಕೆದಾರರಿಂದ ಪ್ಲೇ ಮಾಡುತ್ತದೆ.',
