  'Enter creator email addresses, usernames, or handles to mark their accounts as verified.' => 'ಅವರ ಖಾತೆಗಳನ್ನು ಪರಿಶೀಲಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸಲು ರಚನೆಕಾರರ ಇಮೇಲ್ ವಿಳಾಸಗಳು, ಬಳಕೆದಾರಹೆಸರುಗಳು ಅಥವಾ ಹ್ಯಾಂಡಲ್‌ಗಳನ್ನು ನಮೂದಿಸಿ.',
