  'Email delivery is not configured. Configure MAIL_* settings before sending creator announcements.' => 'ಇಮೇಲ್ ವಿತರಣೆಯನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗಿಲ್ಲ. ರಚನೆಕಾರರ ಪ್ರಕಟಣೆಗಳನ್ನು ಕಳುಹಿಸುವ ಮೊದಲು MAIL_* ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಿ.',
  'Creators verified.' => 'ರಚನೆಕಾರರು ಪರಿಶೀಲಿಸಿದ್ದಾರೆ.',
