  'Your studio settings can be prepared now. Public broadcasting will be enabled with the media engine.' => 'ನಿಮ್ಮ ಸ್ಟುಡಿಯೋ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಈಗ ಸಿದ್ಧಪಡಿಸಬಹುದು. ಮಾಧ್ಯಮ ಎಂಜಿನ್‌ನೊಂದಿಗೆ ಸಾರ್ವಜನಿಕ ಪ್ರಸಾರವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲಾಗುತ್ತದೆ.',
