  'WebRTC engine configured on this server' => 'WebRTC ಎಂಜಿನ್ ಅನ್ನು ಈ ಸರ್ವರ್‌ನಲ್ಲಿ ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗಿದೆ',
  'Set the LiveKit server credentials to enable broadcasting' => 'ಪ್ರಸಾರವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲು ಲೈವ್‌ಕಿಟ್ ಸರ್ವರ್ ರುಜುವಾತುಗಳನ್ನು ಹೊಂದಿಸಿ',
  'LiveKit WebRTC is ready for browser broadcasting.' => 'LiveKit WebRTC ಬ್ರೌಸರ್ ಪ್ರಸಾರಕ್ಕೆ ಸಿದ್ಧವಾಗಿದೆ.',
  'Webcam preview works locally. Public broadcasting requires the LiveKit media engine.' => 'ವೆಬ್‌ಕ್ಯಾಮ್ ಪೂರ್ವವೀಕ್ಷಣೆ ಸ್ಥಳೀಯವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. ಸಾರ್ವಜನಿಕ ಪ್ರಸಾರಕ್ಕೆ LiveKit ಮಾಧ್ಯಮ ಎಂಜಿನ್ ಅಗತ್ಯವಿದೆ.',
  'You are live' => 'ನೀವು ಲೈವ್ ಆಗಿದ್ದೀರಿ',
  'Your camera and microphone are publishing through LiveKit.' => 'ನಿಮ್ಮ ಕ್ಯಾಮರಾ ಮತ್ತು ಮೈಕ್ರೋಫೋನ್ ಲೈವ್‌ಕಿಟ್ ಮೂಲಕ ಪ್ರಕಟಿಸುತ್ತಿದೆ.',
  'Ending...' => 'ಕೊನೆಗೊಳ್ಳುತ್ತಿದೆ...',
  'End live stream' => 'ಲೈವ್ ಸ್ಟ್ರೀಮ್ ಅನ್ನು ಕೊನೆಗೊಳಿಸಿ',
  'Connecting to live stream...' => 'ಲೈವ್ ಸ್ಟ್ರೀಮ್‌ಗೆ ಸಂಪರ್ಕಿಸಲಾಗುತ್ತಿದೆ...',
  'This stream has not started yet.' => 'ಈ ಸ್ಟ್ರೀಮ್ ಇನ್ನೂ ಪ್ರಾರಂಭವಾಗಿಲ್ಲ.',
