  'The invited user must sign in with that account before opening the link.' => 'ಆಹ್ವಾನಿತ ಬಳಕೆದಾರರು ಲಿಂಕ್ ತೆರೆಯುವ ಮೊದಲು ಆ ಖಾತೆಯೊಂದಿಗೆ ಸೈನ್ ಇನ್ ಮಾಡಬೇಕು.',
  'The logo must be a safe SVG file.' => 'ಲೋಗೋ ಸುರಕ್ಷಿತ SVG ಫೈಲ್ ಆಗಿರಬೇಕು.',
  'The new password must be different from the current one.' => 'ಹೊಸ ಪಾಸ್‌ವರ್ಡ್ ಪ್ರಸ್ತುತ ಒಂದಕ್ಕಿಂತ ಭಿನ್ನವಾಗಿರಬೇಕು.',
  'The provided credentials are incorrect.' => 'ಒದಗಿಸಿದ ರುಜುವಾತುಗಳು ತಪ್ಪಾಗಿದೆ.',
  'The two-factor authentication code is invalid.' => 'ಎರಡು ಅಂಶದ ದೃಢೀಕರಣ ಕೋಡ್ ಅಮಾನ್ಯವಾಗಿದೆ.',
